// Immutable game data for the simulation (FG.Sim.GameDb); one instance serves many matches.
// Load from data/simdata.json (a copy of fg-simdata.json generated by D:\foodgang-ref\tools\build_simdata.py).
import { f, FLOAT_MAX, FLOAT_MIN, Vec2 } from '../Core/Vec2.js';
import { Json } from '../Core/Json.js';
import { cosf } from '../Core/CrtMath.js';
import { DEG2RAD } from '../Core/Vec2.js';
import { NavNodeType } from './Enums.js';

const { F, I, B, S, V, count } = Json;

function readShoots(n) {
  const r = [];
  for (let i = 0; i < count(n); i++) {
    const e = n[i];
    r.push({
      frame: Math.trunc(Number(e[0])) | 0,
      angleOffset: f(Number(e[1])),
      offsetY: f(Number(e[2])),
      requiresShootMode: e[3] === true,
    });
  }
  return r;
}

function readVecs(n) {
  const r = [];
  for (let i = 0; i < count(n); i++) r.push({ x: f(n[i][0]), y: f(n[i][1]) });
  return r;
}

function computeInnerBounds(d) {
  d.innerMinX = FLOAT_MIN; d.innerMaxX = FLOAT_MAX; d.floorTop = FLOAT_MIN; d.roofBottom = FLOAT_MAX;
  for (const c of d.colliders) {
    if (c.name === 'WallLeft') d.innerMinX = c.max.x;
    else if (c.name === 'WallRight') d.innerMaxX = c.min.x;
    else if (c.name === 'Floor') d.floorTop = c.max.y;
    else if (c.name === 'Roof') d.roofBottom = c.min.y;
  }
}

export class GameDb {
  constructor() {
    this.dt = 0;
    this.updateFps = 60;
    this.kcc = null;
    this.skins = [];
    this.actions = [];
    this.bullets = [];
    this.maps = [];
    this.modes = [];
    this.rankModifiers = null;
    this.teamVictory = 0; this.teamDefeat = 0; this.teamDraw = 0;
    this._actionByName = new Map();
    this._bulletByName = new Map();
  }

  actionIndex(name) { return name != null && this._actionByName.has(name) ? this._actionByName.get(name) : -1; }
  bulletIndex(name) { return name != null && this._bulletByName.has(name) ? this._bulletByName.get(name) : -1; }

  skinById(skinId) {
    for (const s of this.skins) if (s.skinId === skinId) return s;
    return null;
  }

  skinByName(name) {
    const n = String(name).toUpperCase();
    for (const s of this.skins) if (s.name != null && s.name.toUpperCase() === n) return s;
    return null;
  }

  /** GameDb.Load: `json` is the simdata text or the parsed object. */
  static load(json) {
    const root = typeof json === 'string' ? JSON.parse(json.charCodeAt(0) === 0xfeff ? json.slice(1) : json) : json;
    const db = new GameDb();
    db.updateFps = I(root, 'updateFps', 60);
    const dtRaw = I(root, 'deltaTimeRaw', Math.trunc(65536 / db.updateFps));
    db.dt = f(dtRaw / 65536);

    const k = root.kcc;
    db.kcc = Object.freeze({
      offsetY: F(k, 'offsetY'), radius: F(k, 'radius'), maxPenetration: F(k, 'maxPenetration'),
      penetrationCorrection: F(k, 'penetrationCorrection'), extent: F(k, 'extent'), maxContacts: I(k, 'maxContacts'),
      layerMask: I(k, 'layerMask'), airControl: B(k, 'airControl'), acceleration: F(k, 'acceleration'), braking: F(k, 'braking'),
      baseJumpImpulse: F(k, 'baseJumpImpulse'), gravity: F(k, 'gravity'), maxSlopeDeg: F(k, 'maxSlopeDeg'), maxSlopeSpeed: F(k, 'maxSlopeSpeed'),
      // KccMove evaluates MathF.Cos(MaxSlopeDeg * PI/180) every call; a pure function of data, so computed once here
      groundCos: cosf(f(F(k, 'maxSlopeDeg') * DEG2RAD)),
    });

    const jb = root.bullets;
    for (let i = 0; i < count(jb); i++) {
      const b = jb[i];
      db.bullets.push({
        index: i, name: S(b, 'name'), speed: F(b, 'speed'), hitRadius: F(b, 'hitRadius'), lifeTime: F(b, 'lifeTime'),
        trajectory: I(b, 'trajectory'), destroyType: I(b, 'destroyType'), comeBack: B(b, 'comeBack'),
        rebound: I(b, 'rebound'), snapOnGround: B(b, 'snapOnGround'), number: I(b, 'number'), angleSpread: F(b, 'angleSpread'),
        randomizeSpread: F(b, 'randomizeSpread'), gravityScale: F(b, 'gravityScale'), bounciness: F(b, 'bounciness'),
        explosionRadius: F(b, 'explosionRadius'), tickRate: F(b, 'tickRate'), tickRadius: F(b, 'tickRadius'),
        tickRadiusOffsetY: F(b, 'tickRadiusOffsetY'), scaleOnDistance: F(b, 'scaleOnDistance'), stayOnAgent: B(b, 'stayOnAgent'),
        zoneCount: I(b, 'zoneCount'), zoneSpread: F(b, 'zoneSpread'), zoneRandomizeSpread: B(b, 'zoneRandomizeSpread'),
        tickApplySlow: B(b, 'tickApplySlow'), tickSlowDuration: F(b, 'tickSlowDuration'), onHitApplyPoison: B(b, 'onHitApplyPoison'),
        onHitPoisonDuration: F(b, 'onHitPoisonDuration'), zone: -1,
      });
      db._bulletByName.set(db.bullets[i].name, i);
    }
    for (let i = 0; i < count(jb); i++) {
      const z = S(jb[i], 'zone');
      if (z != null) {
        db.bullets[i].zone = db.bulletIndex(z);
        if (db.bullets[i].zone < 0) throw new Error('bullet ' + db.bullets[i].name + ': zone ' + z + ' not found');
      }
    }

    const ja = root.actions;
    for (let i = 0; i < count(ja); i++) {
      const a = ja[i];
      const d = {
        index: i, name: S(a, 'name'), type: I(a, 'type'), cooldown: F(a, 'cooldown'), hold: B(a, 'hold'),
        slowdownEffect: F(a, 'slowdownEffect'), meleeDrainRate: F(a, 'meleeDrainRate'), clearStatusOnEnd: B(a, 'clearStatusOnEnd'),
        specialSpeedBoost: F(a, 'specialSpeedBoost'), requiresMeleeMode: B(a, 'requiresMeleeMode'),
        statusAddFlags: I(a, 'statusAddFlags'), lockMovement: B(a, 'lockMovement'), rangeMin: F(a, 'rangeMin'),
        rangeMax: F(a, 'rangeMax'), statusDuration: F(a, 'statusDuration'), totalFrames: I(a, 'totalFrames'),
        shoots: readShoots(a.shoots), shootsBoosted: readShoots(a.shootsBoosted),
        meleeWindows: [], meleeOffset: V(a, 'meleeOffset'), meleeSize: V(a, 'meleeSize'), buffs: [],
        dashDirection: V(a, 'dashDirection'), dashDuration: F(a, 'dashDuration'), dashIgnoreGravity: B(a, 'dashIgnoreGravity'),
        dashBackwards: B(a, 'dashBackwards'), bullet: -1, damage: I(a, 'damage'),
        pushBackDuration: F(a, 'pushBackDuration'), pushBackEffect: F(a, 'pushBackEffect'),
      };
      const mw = a.meleeWindows;
      for (let w = 0; w < count(mw); w++) d.meleeWindows.push({ frameStart: Math.trunc(mw[w][0]) | 0, frameEnd: Math.trunc(mw[w][1]) | 0 });
      const bf = a.buffs;
      for (let w = 0; w < count(bf); w++) d.buffs.push(Math.trunc(bf[w]) | 0);
      const bn = S(a, 'bullet');
      if (bn != null) {
        d.bullet = db.bulletIndex(bn);
        if (d.bullet < 0) throw new Error('action ' + d.name + ': bullet ' + bn + ' not found');
      }
      db.actions.push(d);
      db._actionByName.set(d.name, i);
    }

    const js = root.skins;
    for (let i = 0; i < count(js); i++) {
      const s = js[i];
      const p = s.powers;
      const d = {
        index: i, skinId: I(s, 'skinId'), name: S(s, 'name'), hpBase: I(s, 'hpBase'), hitRadius: F(s, 'hitRadius'),
        hitCenterOffsetY: F(s, 'hitCenterOffsetY'), moveSpeed: F(s, 'moveSpeed'), shootOffset: V(s, 'shootOffset'),
        action: db.actionIndex(S(s, 'action')), special: db.actionIndex(S(s, 'special')),
        powerTypes: [], powerValues: [],
      };
      for (let w = 0; w < count(p); w++) { d.powerTypes.push(Math.trunc(p[w][0]) | 0); d.powerValues.push(f(p[w][1])); }
      db.skins.push(d);
    }

    const jm = root.maps;
    for (let i = 0; i < count(jm); i++) {
      const m = jm[i];
      const d = {
        index: i, name: S(m, 'name'), scene: S(m, 'scene'), stageId: S(m, 'stageId'),
        ffaSpawns: readVecs(m.ffaSpawns), ffaRespawns: readVecs(m.ffaRespawns), spawnDuel: readVecs(m.spawnDuel),
        spawnTeam2v2: readVecs(m.spawnTeam2v2), spawnTeam1v3: readVecs(m.spawnTeam1v3),
        spawnTeam3v1: readVecs(m.spawnTeam3v1), spawnDummy: readVecs(m.spawnDummy),
        colliders: [], nav: [], hasNavBounds: false, navMinX: FLOAT_MAX, navMaxX: FLOAT_MIN,
        innerMinX: 0, innerMaxX: 0, floorTop: 0, roofBottom: 0,
      };
      const cols = m.colliders;
      for (let c = 0; c < count(cols); c++) {
        const center = V(cols[c], 'center'), half = V(cols[c], 'half');
        // BoxCollider.Min / Max are properties (Center -/+ Half) in C#; same float ops, computed once
        d.colliders.push({ name: S(cols[c], 'name'), layer: I(cols[c], 'layer'), center, half, min: Vec2.sub(center, half), max: Vec2.add(center, half) });
      }
      const nav = m.nav;
      for (let c = 0; c < count(nav); c++) {
        const n = nav[c];
        const nb = n.neighbors;
        const node = { pos: V(n, 'pos'), type: I(n, 'type'), realHeight: F(n, 'realHeight'), neighbors: [] };
        for (let w = 0; w < count(nb); w++) node.neighbors.push(Math.trunc(nb[w]) | 0);
        d.nav.push(node);
        if (node.type === NavNodeType.Walkable) {
          d.hasNavBounds = true;
          if (node.pos.x < d.navMinX) d.navMinX = node.pos.x;
          if (node.pos.x > d.navMaxX) d.navMaxX = node.pos.x;
        }
      }
      computeInnerBounds(d);
      db.maps.push(d);
    }

    const jmo = root.modes;
    for (let i = 0; i < count(jmo); i++)
      db.modes.push({ group: S(jmo[i], 'group'), label: S(jmo[i], 'label'), goal: I(jmo[i], 'goal'), team: I(jmo[i], 'team') });

    const df = root.difficulty;
    if (df != null) {
      db.rankModifiers = (df.rankModifiers || []).map((v) => f(v));
      db.teamVictory = F(df, 'teamVictory'); db.teamDefeat = F(df, 'teamDefeat'); db.teamDraw = F(df, 'teamDraw');
    }
    return db;
  }
}
